$st=$pdo->prepare("SELECT DISTINCT tf.papercode,COALESCE(c.coursetitle,tf.papercode) coursetitle FROM timetablefaculty tf LEFT JOIN courses c ON UPPER(c.coursecode)=UPPER(tf.papercode) WHERE UPPER(tf.fid)=UPPER(?) ORDER BY tf.papercode");$st->execute([$user['staff_code']??'']);$assigned=$st->fetchAll(PDO::FETCH_ASSOC);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/navbar.php';require_once __DIR__.'/../../includes/sidebar.php';
?>
<main class="max-w-7xl mx-auto px-4 sm:px-6 py-6 space-y-6">
 <header class="rounded-2xl bg-slate-950 text-white p-6"><div class="text-xs uppercase tracking-widest text-orange-300 font-bold">Teaching Staff Portal · Page 4</div><h1 class="text-2xl font-black mt-1">Final Question Slot Creation</h1><p class="text-sm text-slate-300 mt-2">Choose a Dean template, then allocate one or more eligible Unit / Sub-unit combinations to every slot. The Dean template remains unchanged.</p></header>
 <section class="bg-white border border-slate-200 rounded-2xl p-5 space-y-4"><h2 class="font-black">Step 1 — Course and academic context</h2><div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-3">
 <label class="text-xs font-bold text-slate-600">Allocated Course<select id="course" class="mt-1 w-full rounded-xl border-slate-300 p-3"><option value="">Select course</option><?php foreach($assigned as $c):?><option value="<?=htmlspecialchars($c['papercode'],ENT_QUOTES)?>"><?=htmlspecialchars($c['papercode'].' — '.$c['coursetitle'])?></option><?php endforeach;?></select></label>
 <label class="text-xs font-bold text-slate-600">Academic Year<input id="year" class="mt-1 w-full rounded-xl border-slate-300 p-3" placeholder="2026-2027" maxlength="9"></label>
 <label class="text-xs font-bold text-slate-600">Semester<select id="semester" class="mt-1 w-full rounded-xl border-slate-300 p-3"><option value="">Select semester</option><?php for($i=1;$i<=8;$i++):?><option value="<?=$i?>">Semester <?=$i?></option><?php endfor;?></select></label>
 <label class="text-xs font-bold text-slate-600">Year of Programme<select id="programme" class="mt-1 w-full rounded-xl border-slate-300 p-3"><option value="">Select year</option><option>I</option><option>II</option><option>III</option><option>IV</option></select></label>
 <label class="text-xs font-bold text-slate-600">Language<select id="language" class="mt-1 w-full rounded-xl border-slate-300 p-3"><option value="EN">English</option><option value="TL">Tamil</option><option value="HI">Hindi</option></select></label></div>
 <div class="flex flex-wrap gap-3 items-end"><label class="text-xs font-bold text-slate-600">Minimum eligible questions per selected Unit/Sub-unit<input id="minimum" type="number" min="1" max="20" value="1" readonly class="mt-1 block w-28 rounded-xl border-slate-300 p-3 bg-slate-100"></label><p id="contextStatus" class="text-xs text-slate-500 pb-3">Select a course and academic context to view matching published Dean templates.</p></div></section>
 <section class="bg-white border border-slate-200 rounded-2xl p-5 space-y-4"><div class="flex flex-wrap justify-between gap-3 items-center"><div><h2 class="font-black">Step 2 — Dean question paper template</h2><p class="text-xs text-slate-500">Only active, published templates are shown. Context fields are matched when the Dean template contains them.</p></div><select id="template" class="min-w-64 rounded-xl border-slate-300 p-3 text-sm" disabled><option>Select course/context first</option></select></div><div id="templateSummary" class="hidden rounded-xl bg-slate-50 border border-slate-200 p-4 text-sm"></div></section>
 <section id="workspace" class="hidden bg-white border border-slate-200 rounded-2xl p-5 space-y-4"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-black">Step 3 — Slot allocation table</h2><p class="text-xs text-slate-500">Select a slot to choose one or more Unit / Sub-unit combinations.</p></div><span id="progress" class="rounded-full bg-indigo-50 text-indigo-700 px-4 py-2 text-sm font-black">0 of 0 slots allotted</span></div>
 <div class="overflow-x-auto"><table class="w-full text-sm border-collapse"><thead><tr class="bg-slate-100 text-left"><th class="p-3">Question No.</th><th class="p-3">Section</th><th class="p-3">Marks</th><th class="p-3">K Level</th><th class="p-3">CO Level</th><th class="p-3">Allotted Units / Sub-units</th><th class="p-3">Eligible Questions</th><th class="p-3">Status</th><th class="p-3">Action</th></tr></thead><tbody id="slotRows"><tr><td colspan="9" class="p-5 text-center text-slate-500">Select a published template.</td></tr></tbody></table></div>
 <div class="flex flex-wrap justify-between items-center gap-3 border-t pt-4"><p id="saveStatus" class="text-xs text-slate-500">Every slot must have at least one valid allocation.</p><button id="saveBtn" type="button" disabled class="rounded-xl bg-indigo-600 text-white font-bold px-5 py-3 disabled:opacity-40">Save Final Blueprint</button></div></section>
</main>
<div id="allocationModal" class="hidden fixed inset-0 z-[100] bg-slate-950/60 p-3 sm:p-6 overflow-y-auto"><div class="max-w-3xl mx-auto mt-8 bg-white rounded-2xl shadow-2xl overflow-hidden"><div class="p-5 border-b flex justify-between items-start gap-3"><div><h3 id="modalTitle" class="font-black text-lg">Allocate slot</h3><p id="modalHint" class="text-xs text-slate-500 mt-1">Choose one or more eligible combinations.</p></div><button id="closeModal" class="text-slate-500 text-2xl">×</button></div><div id="combinationList" class="p-5 space-y-2"><p class="text-sm text-slate-500">Loading eligibility…</p></div><div class="p-5 border-t flex justify-end gap-2"><button id="cancelModal" class="rounded-xl border px-4 py-2">Cancel</button><button id="applyModal" class="rounded-xl bg-indigo-600 text-white font-bold px-4 py-2">Apply selections</button></div></div></div>
<script>
const csrf=<?=json_encode($_SESSION['qps_review_csrf'])?>,base=<?=json_encode(rtrim(getBaseUrl(),'/'))?>, $=id=>document.getElementById(id);
let catalog=[],template=null,slots=[],allocations={},activeSlot=null,minimum=1;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,data){const r=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,csrf})});const j=await r.json();if(!r.ok||!j.success)throw Error(j.message||'Request failed');return j.data;}
function context(){return {paper_code:$('course').value,academic_year:$('year').value.trim(),semester:Number($('semester').value),programme_year:$('programme').value,language:$('language').value};}
function contextValid(){const c=context();return !!c.paper_code&&/^((19|20)\d{2})-((19|20)\d{2})$/.test(c.academic_year)&&c.semester>=1&&c.semester<=8&&!!c.programme_year;}
async function loadCatalog(){if(!contextValid()){$('template').disabled=true;$('template').innerHTML='<option>Complete course context first</option>';return;}$('template').disabled=true;$('template').innerHTML='<option>Loading templates…</option>';try{const d=await api('/api/teaching_dean_templates.php',{action:'catalog'});catalog=d||[];const c=context();catalog=catalog.filter(t=>(!t.academic_year||t.academic_year===c.academic_year)&&(!t.semester||Number(t.semester)===c.semester)&&(!t.year_of_programme||String(t.year_of_programme).toUpperCase()===c.programme_year));$('template').innerHTML='<option value="">Select published template</option>'+catalog.map(t=>`<option value="${t.id}">${esc(t.template_name)} · ${t.total_marks} marks · ${t.section_count} sections · ${t.slot_count} slots</option>`).join('');$('template').disabled=false;$('contextStatus').textContent=`${catalog.length} matching published template(s) found. Minimum eligible count is controlled by the COE setting.`;}catch(e){$('contextStatus').textContent=e.message;}}
function updateProgress(){const total=slots.length,done=slots.filter(s=>(allocations[s.id]||[]).length>0).length;$('progress').textContent=`${done} of ${total} slots allotted`;$('saveBtn').disabled=!total||done!==total;}
function renderRows(){const groups=template.sections||[];$('slotRows').innerHTML=slots.map((s,i)=>{const a=allocations[s.id]||[],count=a.reduce((n,x)=>n+Number(x.eligible_count||0),0),units=a.map(x=>`U${x.unit_no} / ${esc(x.sub_unit)}`).join(', ');return `<tr class="border-b"><td class="p-3 font-bold">${esc(s.slot_label||`Q${i+1}`)}</td><td class="p-3">${esc((groups.find(g=>Number(g.id)===Number(s.section_id))||{}).section_name||'')}</td><td class="p-3">${esc(s.marks)}</td><td class="p-3">${esc(s.k_level)}</td><td class="p-3">${esc(s.co_level)}</td><td class="p-3 min-w-48">${units||'<span class="text-slate-400">Not allotted</span>'}</td><td class="p-3">${count}</td><td class="p-3">${a.length?'<span class="text-emerald-700 font-bold">Allotted</span>':'<span class="text-amber-700 font-bold">Pending</span>'}</td><td class="p-3"><button data-slot="${s.id}" class="rounded-lg border border-indigo-200 text-indigo-700 px-3 py-2 text-xs font-bold">${a.length?'Edit':'Allocate'}</button></td></tr>`;}).join('');document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>openSlot(b.dataset.slot));updateProgress();}
async function openSlot(id){activeSlot=String(id);const s=slots.find(x=>String(x.id)===activeSlot);$('allocationModal').classList.remove('hidden');$('modalTitle').textContent=`${s.slot_label} · ${s.marks} marks · ${s.k_level} · ${s.co_level}`;$('combinationList').innerHTML='<p class="text-sm text-slate-500">Checking matching draft questions…</p>';
 try{const d=await api('/api/teaching_slot_eligibility.php',{...context(),marks:s.marks,k_level:s.k_level,co_level:s.co_level,minimum_eligible:minimum});minimum=Number(d.minimum_eligible||1);$('minimum').value=minimum;const chosen=new Set((allocations[activeSlot]||[]).map(x=>`${x.unit_no}|${x.sub_unit}`));if(!d.combinations.length){$('combinationList').innerHTML='<p class="text-sm text-rose-600">No matching draft questions found for this slot.</p>';return;}$('modalHint').textContent=`${d.eligible_questions} eligible questions across ${d.combination_count} Unit/Sub-unit combinations. Minimum per selected combination: ${minimum}.`;$('combinationList').innerHTML=d.combinations.map(x=>{const key=`${x.unit_no}|${x.sub_unit}`;return `<label class="flex items-center justify-between gap-3 rounded-xl border p-3 ${x.warning?'border-amber-300 bg-amber-50':'border-slate-200'}"><span class="flex items-center gap-3"><input type="checkbox" class="combo-check" value="${esc(key)}" ${chosen.has(key)?'checked':''} ${x.warning?'disabled':''}><span><b>Unit ${x.unit_no} / Sub-unit ${esc(x.sub_unit)}</b><small class="block text-slate-500">${x.eligible_count} eligible questions</small></span></span>${x.warning?'<b class="text-amber-700 text-xs">Below minimum</b>':'<b class="text-emerald-700 text-xs">Eligible</b>'}</label>`;}).join('');$('applyModal').onclick=()=>{const checked=[...document.querySelectorAll('.combo-check:checked')].map(el=>{const [unit,sub]=el.value.split('|');const row=d.combinations.find(x=>String(x.unit_no)===unit&&String(x.sub_unit)===sub);return {unit_no:Number(unit),sub_unit:sub,eligible_count:Number(row.eligible_count)};});allocations[activeSlot]=checked;$('allocationModal').classList.add('hidden');renderRows();};
 }catch(e){$('combinationList').innerHTML=`<p class="text-sm text-rose-600">${esc(e.message)}</p>`;}}
async function loadTemplate(){const id=Number($('template').value);template=null;slots=[];allocations={};$('workspace').classList.add('hidden');$('templateSummary').classList.add('hidden');if(!id)return;try{template=await api('/api/teaching_dean_templates.php',{action:'get',template_id:id});const c=context();if(template.academic_year&&template.academic_year!==c.academic_year)throw Error('Template academic year does not match selected context.');if(template.semester&&Number(template.semester)!==c.semester)throw Error('Template semester does not match selected context.');if(template.year_of_programme&&String(template.year_of_programme).toUpperCase()!==c.programme_year)throw Error('Template programme year does not match selected context.');slots=template.slots||[];if(!slots.length)throw Error('Selected template has no active slots.');$('templateSummary').innerHTML=`<b>${esc(template.template_name)}</b> · ${template.total_marks} marks · ${template.sections.length} sections · ${slots.length} slots`;$('templateSummary').classList.remove('hidden');const saved=await api('/api/teaching_save_final_allotment.php',{action:'load_saved',...c,template_id:id});if(saved.saved){saved.slots.forEach(s=>allocations[String(s.template_slot_id)]=s.allocations||[]);const snap=typeof saved.blueprint.template_snapshot==='string'?JSON.parse(saved.blueprint.template_snapshot||'{}'):(saved.blueprint.template_snapshot||{});if(Array.isArray(snap.slots)&&snap.slots.length){const snapSections=Object.values(snap.sections||{}).map(x=>({id:Number(x.section_id),section_name:x.section_title,section_type:x.section_type}));slots=snap.slots.map(x=>({id:Number(x.template_slot_id),section_id:Number(x.section_id),slot_label:x.slot_label,marks:Number(x.marks),k_level:x.k_level,co_level:x.co_level,question_type:x.question_type,sort_order:0}));template={...template,template_name:saved.blueprint.template_name_snapshot||snap.template_name||template.template_name,total_marks:Number(snap.total_marks||saved.blueprint.total_marks),sections:snapSections,slots};$('templateSummary').innerHTML=`<b>${esc(template.template_name)}</b> · ${template.total_marks} marks · ${snapSections.length} saved sections · ${slots.length} saved slots <span class="ml-2 text-amber-700 font-bold">Saved snapshot</span>`;} $('saveStatus').textContent='Saved snapshot restored. Original slot labels, marks, K levels and CO levels are preserved even if the Dean later edits the template.';}else $('saveStatus').textContent='No saved allocation. Allocate every slot to continue.';$('workspace').classList.remove('hidden');renderRows();}catch(e){$('contextStatus').textContent=e.message;}}
async function save(){minimum=Math.max(1,Math.min(20,Number($('minimum').value)||1));const missing=slots.filter(s=>!(allocations[s.id]||[]).length);if(missing.length){$('saveStatus').textContent=`${missing.length} slot(s) still need allocations.`;return;}const payload={action:'save',...context(),template_id:template.id,minimum_eligible:minimum,slots:slots.map(s=>({template_slot_id:s.id,allocations:allocations[s.id]||[]}))};$('saveBtn').disabled=true;$('saveStatus').textContent='Server validating and saving every slot…';try{const d=await api('/api/teaching_save_final_allotment.php',payload);$('saveStatus').textContent=`Saved successfully: ${d.assigned} of ${d.total} slots.`;if(window.Swal)Swal.fire({icon:'success',title:'Final Blueprint Saved',text:'Your slot allocations have been saved.'});}catch(e){$('saveStatus').textContent=e.message;if(window.Swal)Swal.fire({icon:'error',title:'Save failed',text:e.message});}finally{updateProgress();}}
['course','year','semester','programme','language'].forEach(id=>$(id).addEventListener('change',()=>{ $('template').value='';$('workspace').classList.add('hidden');loadCatalog();}));$('template').addEventListener('change',loadTemplate);$('saveBtn').addEventListener('click',save);$('closeModal').onclick=$('cancelModal').onclick=()=>$('allocationModal').classList.add('hidden');
</script>
<?php require_once __DIR__.'/../../includes/footer.php'; ?>
